<template>
  <div class="office-page"><AppSidebar/><main class="main"><header class="head"><div><h2>{{ t('title') }}</h2><p>{{ t('subtitle') }}</p></div><div><el-tag type="primary">{{ t('meetings') }} {{ meetings.length }}</el-tag><el-tag type="warning">{{ t('todo') }} {{ tasks.length }}</el-tag><el-button size="small" type="primary" @click="openCreate">{{ t('newMeeting') }}</el-button></div></header>
    <div class="layout"><section class="meetings panel"><div class="panel-head"><b>{{ t('recent') }}</b><span>{{ t('clickDetail') }}</span></div><div v-for="item in meetings" :key="item.id" class="meeting-card"><div class="date"><b>{{ date(item.start_time) }}</b><small>{{ time(item.start_time) }}-{{ time(item.end_time) }}</small></div><div class="meeting-body"><button @click="showDetail(item)">{{ item.title }}</button><p><el-tag type="mini" size="mini">{{ t('scheduled') }}</el-tag> {{ item.location || t('online') }} · {{ (item.participants||[]).length }} {{ t('attendees') }}</p><a v-if="item.meeting_link" :href="item.meeting_link" target="_blank">{{ t('enterTencent') }}</a></div></div><el-empty v-if="!meetings.length" :description="t('emptyMeeting')"/></section>
      <section class="tasks panel"><div class="panel-head"><b>{{ t('actions') }}</b><span>{{ t('myTasks') }}</span></div><div v-for="task in taskCards" :key="task.id" class="task-card"><span class="status" :class="task.state"></span><div><b>{{ task.title }}</b><small>{{ task.deadline }}</small></div><el-tag size="mini" :type="task.state==='done'?'success':task.state==='doing'?'primary':'info'">{{ stateLabel(task.state) }}</el-tag></div><el-empty v-if="!taskCards.length" :description="t('emptyTask')"/></section>
      <aside class="side"><section class="panel"><div class="panel-head"><b>{{ t('timeline') }}</b><span>{{ t('today') }}</span></div><div v-for="s in schedules.slice(0,6)" :key="s.id" class="timeline"><i :class="s.event_type==='meeting'?'blue':'green'"></i><div><b>{{ time(s.start_time) }} {{ s.title }}</b><small>{{ s.event_type==='meeting'?t('meetingPlan'):t('actionDeadline') }}</small></div></div></section><section class="panel notices"><div class="panel-head"><b>{{ t('reminders') }}</b><el-badge :value="unread" :hidden="!unread"/></div><div v-for="n in notices.slice(0,4)" :key="n.id" class="notice"><b>{{ n.title }}</b><small>{{ n.content }}</small></div><el-empty v-if="!notices.length" :image-size="45" :description="t('emptyNotice')"/></section></aside></div>
  </main><el-dialog :title="t('newMeeting')" :visible.sync="visible" width="560px"><el-form :model="form" label-width="88px" size="small"><el-form-item :label="t('subject')"><el-input v-model="form.title"/></el-form-item><el-form-item :label="t('time')"><el-date-picker v-model="form.range" type="datetimerange" value-format="yyyy-MM-ddTHH:mm:ss" :start-placeholder="t('start')" :end-placeholder="t('end')" style="width:100%"/></el-form-item><el-form-item :label="t('attendees')"><el-select v-model="form.participantIds" multiple style="width:100%"><el-option v-for="m in members" :key="m.user_id" :label="m.display_name" :value="m.user_id"/></el-select></el-form-item><el-form-item :label="t('tencent')"><el-input v-model="form.meeting_link" :placeholder="t('tencentHint')"/></el-form-item></el-form><span slot="footer"><el-button @click="visible=false">{{ t('cancel') }}</el-button><el-button type="primary" @click="create">{{ t('createNotify') }}</el-button></span></el-dialog><el-dialog :title="detail&&detail.title" :visible.sync="detailVisible" width="620px"><div v-if="detail"><el-descriptions :column="2" border size="small"><el-descriptions-item :label="t('time')">{{ detail.start_time }} - {{ detail.end_time }}</el-descriptions-item><el-descriptions-item :label="t('attendees')">{{ (detail.participants||[]).map(x=>x.display_name).join('、') || '-' }}</el-descriptions-item><el-descriptions-item :label="t('tencent')"><a v-if="detail.meeting_link" :href="detail.meeting_link" target="_blank">{{ t('enterTencent') }}</a><span v-else>-</span></el-descriptions-item><el-descriptions-item :label="t('place')">{{ detail.location || t('online') }}</el-descriptions-item></el-descriptions><el-divider>{{ t('minutes') }}</el-divider><pre>{{ detail.minutes || t('noMinutes') }}</pre></div></el-dialog></div>
</template>
<script>
import AppSidebar from '../components/Sidebar/index.vue'
const Z={title:'\u4f1a\u8bae\u4efb\u52a1',subtitle:'\u4f1a\u8bae\u7ec4\u7ec7\u3001\u884c\u52a8\u9879\u3001\u4e2a\u4eba\u65f6\u95f4\u7ebf\u4e0e\u63d0\u9192\u5728\u6b64\u7edf\u4e00\u7ba1\u7406',meetings:'\u4f1a\u8bae',todo:'\u5f85\u529e',newMeeting:'\u65b0\u5efa\u4f1a\u8bae',recent:'\u8fd1\u671f\u4f1a\u8bae',clickDetail:'\u70b9\u51fb\u4e3b\u9898\u67e5\u770b\u8be6\u60c5',scheduled:'\u5f85\u53ec\u5f00',online:'\u7ebf\u4e0a\u4f1a\u8bae',attendees:'\u4f4d\u53c2\u4f1a\u4eba',enterTencent:'\u8fdb\u5165\u817e\u8baf\u4f1a\u8bae',emptyMeeting:'\u6682\u65e0\u4f1a\u8bae',actions:'\u884c\u52a8\u9879',myTasks:'\u6211\u7684\u5f85\u529e',emptyTask:'\u6682\u65e0\u884c\u52a8\u9879',timeline:'\u4e2a\u4eba\u65f6\u95f4\u7ebf',today:'\u4eca\u65e5',meetingPlan:'\u4f1a\u8bae\u5b89\u6392',actionDeadline:'\u884c\u52a8\u9879\u622a\u6b62',reminders:'\u63d0\u9192\u901a\u77e5',emptyNotice:'\u6682\u65e0\u6d88\u606f',subject:'\u4f1a\u8bae\u4e3b\u9898',time:'\u4f1a\u8bae\u65f6\u95f4',start:'\u5f00\u59cb',end:'\u7ed3\u675f',tencent:'\u817e\u8baf\u4f1a\u8bae',tencentHint:'\u7c98\u8d34\u4f1a\u8bae\u94fe\u63a5\u6216\u4f1a\u8bae\u53f7',cancel:'\u53d6\u6d88',createNotify:'\u521b\u5efa\u5e76\u901a\u77e5',place:'\u5730\u70b9',minutes:'\u4f1a\u8bae\u7eaa\u8981',noMinutes:'\u6682\u65e0\u7eaa\u8981\uff0c\u4f1a\u540e\u53ef\u4eba\u5de5\u6574\u7406\u6216\u4f7f\u7528 AI \u751f\u6210\u8349\u7a3f\u3002',done:'\u5df2\u5b8c\u6210',doing:'\u8fdb\u884c\u4e2d',todoLabel:'\u672a\u5b8c\u6210'}
export default {components:{AppSidebar},data:()=>({visible:false,detailVisible:false,detail:null,form:{range:[],participantIds:[]}}),computed:{ws(){return this.$store.getters['workspace/activeWorkspace']||{}},meetings(){return this.$store.state.office.meetings},schedules(){return this.$store.state.office.schedules},members(){return (this.$store.state.office.organization||{members:[]}).members},notices(){return this.$store.state.office.notifications},unread(){return this.$store.state.office.unreadNotifications},tasks(){return this.schedules.filter(x=>x.event_type==='task')},taskCards(){return this.tasks.map((x,i)=>({id:x.id,title:x.title,deadline:x.start_time,state:x.status==='done'?'done':i%3===0?'doing':'todo'}))}},watch:{'ws.id':{immediate:true,handler(){this.load()}}},methods:{t(k){return Z[k]||k},async load(){if(!this.ws.id||this.ws.domain!=='office')return;await Promise.all([this.$store.dispatch('office/loadMeetings',this.ws.id),this.$store.dispatch('office/loadSchedules',this.ws.id),this.$store.dispatch('office/loadOrganization',this.ws.id),this.$store.dispatch('office/loadNotifications',this.ws.id)])},openCreate(){this.form={range:[],participantIds:[]};this.visible=true},async create(){if(!this.form.title||this.form.range.length!==2)return this.$message.warning('\u8bf7\u5b8c\u6574\u586b\u5199\u4f1a\u8bae\u4e3b\u9898\u548c\u65f6\u95f4');const participants=this.members.filter(m=>this.form.participantIds.includes(m.user_id)).map(m=>({user_id:m.user_id,display_name:m.display_name}));await this.$store.dispatch('office/createMeeting',{workspace_id:this.ws.id,title:this.form.title,start_time:this.form.range[0],end_time:this.form.range[1],participants,meeting_link:this.form.meeting_link});this.visible=false;this.load()},async showDetail(item){this.detail=await this.$store.dispatch('office/getMeeting',item.id);this.detailVisible=true},date(v){return(v||'').slice(5,10)},time(v){return(v||'').slice(11,16)},stateLabel(s){return s==='done'?Z.done:s==='doing'?Z.doing:Z.todoLabel}}}
</script>
<style scoped>
.office-page{display:flex;min-height:100vh;padding:12px;gap:12px;background:#f3f6fb}.main{flex:1;padding:18px;background:#fff;border-radius:12px}.head,.panel-head{display:flex;justify-content:space-between;align-items:center}.head{border-bottom:1px solid #edf0f5;padding-bottom:13px;margin-bottom:14px}.head h2{margin:0 0 4px}.head p,.panel-head span{margin:0;color:#8592a6;font-size:13px}.head .el-tag,.head .el-button{margin-left:7px}.layout{display:grid;grid-template-columns:1.3fr 1fr .9fr;gap:13px}.panel{border:1px solid #e6edf5;border-radius:9px;padding:11px;background:#fbfcff}.panel-head{margin-bottom:8px}.meeting-card{display:flex;border-top:1px solid #e9eff6;padding:10px 0;gap:10px}.date{width:70px;text-align:center;border-right:1px solid #e5ebf3}.date b,.date small{display:block}.date small,.task-card small,.timeline small,.notice small{color:#8492a6;font-size:11px}.meeting-body{min-width:0}.meeting-body button{padding:0;border:0;background:none;color:#286fc0;font-weight:700;cursor:pointer}.meeting-body p{margin:5px 0;font-size:12px;color:#6b788b}.meeting-body a{font-size:12px;color:#159776}.task-card{display:flex;align-items:center;gap:8px;padding:9px 0;border-top:1px dashed #e3eaf2}.status{width:8px;height:35px;border-radius:4px;background:#aab5c4}.status.done{background:#4dbb82}.status.doing{background:#4f92ef}.task-card div{flex:1;min-width:0}.task-card b,.task-card small{display:block}.timeline{display:flex;gap:8px;padding:8px 0;border-top:1px dashed #e5ecf4}.timeline i{width:8px;height:8px;border-radius:50%;margin-top:4px}.blue{background:#4f92ef}.green{background:#4dbb82}.timeline b,.timeline small,.notice b,.notice small{display:block;font-size:12px}.notices{margin-top:12px}.notice{padding:7px 0;border-top:1px dashed #e5ecf4}@media(max-width:1100px){.layout{grid-template-columns:1fr 1fr}.side{grid-column:1/-1}}@media(max-width:760px){.layout{grid-template-columns:1fr}.side{grid-column:auto}}
</style>
